// Canvas renderer + pointer handling. This file owns pixels and gestures and decides nothing
// about legality: a tap hands `main.js` a palette index or a peg position, and js/core/game.js
// is the only place that knows whether a row may be submitted. So the drawing can lag the
// rules but can never show a move the rules forbid.
//
// Pegs, the feedback slots and the palette are still drawn from the colour table in
// js/core/codes.js — the one bitmap here is the desk the rows sit on: assets/img/pegboard.png,
// a tileable texture generated by assets/gen/gen_art.py. It is decoration only, and the board
// draws identically (flat row wash) if it never loads.
//
// MOTION IS IN SECONDS, NOT FRAMES. Every animated quantity advances by `dt` inside one rAF
// callback, so a 30Hz tablet and a 120Hz phone show the same row growing in over the same wall
// time; `paused` stops the accumulator entirely rather than letting it bank the elapsed time.
//
// The two exported probes are the contract with tools/playtest.mjs: `pegPoint(row, col)` and
// `palettePoint(c)` return CLIENT coordinates — the same mapping the click handler inverts, run
// forwards, so a headless Chrome can press exactly where a human would aim.

import { MAX_ROWS } from './core/game.js';
import { COLOR_SWATCH, COLOR_NAMES } from './core/codes.js';

const PAD = 16;
const INK = '#e6e9ef';
const DIM = 'rgba(230, 233, 239, 0.30)';
const SLOT = 'rgba(230, 233, 239, 0.10)';
const SLOT_EDGE = 'rgba(230, 233, 239, 0.22)';
const ROW_BG = 'rgba(230, 233, 239, 0.04)';
const ACTIVE = 'rgba(224, 166, 60, 0.16)';
const ACTIVE_EDGE = '#e0a63c';
const BLACK_PEG = '#12141a';
const WHITE_PEG = '#f2f4f8';
const TEX = 'assets/img/pegboard.png';
const TEX_SIZE = 512;
// The newest row grows in over ~0.14s and the desk keeps breathing for a moment after, then the
// loop parks itself. ANIM_SPEED is per SECOND — the old `anim + 0.12` per frame was the same
// number only at exactly 60Hz.
const ANIM_SPEED = 7.2;
const LIVE_WINDOW = 1.6;
// A finger is not a mouse: below this, a tap target is a miss waiting to happen.
const MIN_HIT = 44;

function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.max(0, Math.min(r, w / 2, h / 2));
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

export function createView(canvas, { space, onPalette, onPeg, onRow } = {}) {
  const ctx = canvas.getContext('2d');
  const L = space.L;
  const C = space.C;
  let game = null;
  // Geometry in CSS pixels, recomputed on measure(). `pitch` is the distance between two peg
  // centres, `peg` the drawn size, so a slot always has a visible gap inside a row.
  let geo = { peg: 30, pitch: 36, ox: PAD, oy: PAD, rowH: 44, fbX: 0, palY: 0, palR: 14, palX: PAD, w: 320, h: 320 };
  let anim = 0; // 0..1, the last row sliding in
  let live = 0; // seconds of "the desk is breathing" left after the last board change
  let clock = 0; // seconds the view has actually advanced — frozen by pause, not by wall time
  let frames = 0;
  // null, not 0: a 0 sentinel makes the first callback compute a dt from the epoch (or, in a
  // sandbox whose clock starts at 1000ms, eat a whole frame), and either way the row lands with
  // one frame's worth of error that looks exactly like a frame-rate dependency.
  let last = null;
  let raf = 0;
  let paused = false;
  let reduced = false;
  let pattern = null;

  function loadTexture() {
    if (typeof Image === 'undefined') return;
    const img = new Image();
    img.onload = () => {
      if (typeof ctx.createPattern !== 'function') return;
      const p = ctx.createPattern(img, 'repeat');
      if (p) {
        pattern = p;
        draw();
      }
    };
    img.onerror = () => { pattern = null; };
    img.src = TEX;
  }

  function measure() {
    const box = canvas.getBoundingClientRect();
    const dpr = Math.max(1, Math.min(3, window.devicePixelRatio || 1));
    const W = Math.max(200, Math.round(box.width));
    const H = Math.max(220, Math.round(box.height));
    canvas.width = Math.round(W * dpr);
    canvas.height = Math.round(H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    // One row is: gutter + L pegs + gap + a 2x2 feedback block, all in units of `peg`. The
    // palette under it needs one row of its own. Solving for `peg` keeps the board identical in
    // proportion from a phone to a desktop instead of overflowing on the small end.
    const rowUnits = L * 1.22 + 2.35;
    const heightUnits = MAX_ROWS * 1.36 + 3.6;
    const peg = Math.max(9, Math.min(42, Math.floor(Math.min((W - PAD * 2) / rowUnits, (H - PAD * 2) / heightUnits))));
    const pitch = Math.round(peg * 1.22);
    const rowH = Math.round(peg * 1.36);
    const fbX = Math.round(PAD + peg * 0.55 + pitch * L + peg * 0.5);
    geo = {
      peg,
      pitch,
      ox: PAD,
      oy: PAD,
      rowH,
      fbX,
      palY: Math.round(PAD + rowH * MAX_ROWS + peg * 1.1),
      palR: Math.round(Math.min(peg * 0.62, (W - PAD * 2) / (C * 2.2))),
      palX: 0,
      w: W,
      h: H,
    };
    const span = geo.palR * 2 * C + (C - 1) * geo.palR;
    geo.palX = Math.round((W - span) / 2) + geo.palR;
    draw();
  }

  function localPoint(ev) {
    const box = canvas.getBoundingClientRect();
    return { x: ev.clientX - box.left, y: ev.clientY - box.top };
  }

  // Centre of a drawn peg: `row` 0..MAX_ROWS-1 top to bottom, `col` 0..L-1.
  function pegXY(row, col) {
    return {
      x: geo.ox + geo.peg / 2 + geo.pitch * col,
      y: geo.oy + row * geo.rowH + geo.rowH / 2,
    };
  }

  // Nearest-target hit testing with a MIN_HIT floor. The drawn cell is often smaller than a
  // finger — 10 rows on a phone gives a ~27px band — and "which cell contains this point" would
  // then silently hand the player a 27px target. "Which centre is closest, within MIN_HIT/2"
  // keeps the tap where it was aimed and never maps it to a cell more than 22px away.
  function paletteHit(p) {
    const band = Math.max(geo.palR * 1.6, MIN_HIT / 2);
    if (Math.abs(p.y - geo.palY) > band) return -1;
    const rad = Math.max(geo.palR * 1.15, MIN_HIT / 2);
    let best = -1;
    let bestD = Infinity;
    for (let c = 0; c < C; c++) {
      const cx = geo.palX + c * geo.palR * 3;
      const d = Math.hypot(p.x - cx, p.y - geo.palY);
      if (d <= rad && d < bestD) {
        bestD = d;
        best = c;
      }
    }
    return best;
  }

  function rowHit(p) {
    const row = Math.round((p.y - geo.oy - geo.rowH / 2) / geo.rowH);
    if (row < 0 || row >= MAX_ROWS) return null;
    const cy = geo.oy + row * geo.rowH + geo.rowH / 2;
    if (Math.abs(p.y - cy) > Math.max(geo.rowH, MIN_HIT) / 2) return null;
    const col = Math.round((p.x - geo.ox - geo.peg / 2) / geo.pitch);
    if (col < 0 || col >= L) return { row, col: -1 };
    const cx = geo.ox + geo.peg / 2 + geo.pitch * col;
    if (Math.abs(p.x - cx) > Math.max(geo.pitch, MIN_HIT) / 2) return { row, col: -1 };
    return { row, col };
  }

  function down(ev) {
    if (!game || paused) return;
    const p = localPoint(ev);
    // Palette first: it is the only control while a row is in progress, and a mistap must not
    // eat a peg.
    const c = paletteHit(p);
    if (c >= 0) {
      if (onPalette) onPalette(c);
      ev.preventDefault();
      return;
    }
    const hit = rowHit(p);
    if (!hit) return;
    if (hit.row === game.rows.length && game.draft.length && hit.col >= 0) {
      if (onPeg) onPeg(hit.col);
    } else if (hit.row < game.rows.length && onRow) {
      onRow(hit.row);
    } else {
      return;
    }
    ev.preventDefault();
  }

  // pointerdown where it exists; the two legacy events only as the fallback, never alongside it,
  // or a single tap on a hybrid device fires twice and puts two pegs.
  let gesture = 'none';
  let onTouch = null;
  if (typeof window !== 'undefined' && ('onpointerdown' in window || typeof window.PointerEvent === 'function')) {
    canvas.addEventListener('pointerdown', down);
    gesture = 'pointerdown';
  } else {
    onTouch = (ev) => {
      const t = ev.touches && ev.touches[0];
      if (!t) return;
      down({ clientX: t.clientX, clientY: t.clientY, preventDefault: () => ev.preventDefault() });
    };
    canvas.addEventListener('touchstart', onTouch, { passive: false });
    canvas.addEventListener('mousedown', down);
    gesture = 'touchstart+mousedown';
  }

  loadTexture();

  function peg(ctx, x, y, r, colour) {
    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,0.45)';
    ctx.shadowBlur = r * 0.35;
    ctx.shadowOffsetY = r * 0.14;
    ctx.fillStyle = colour;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    const g = ctx.createRadialGradient(x - r * 0.4, y - r * 0.5, r * 0.15, x, y, r);
    g.addColorStop(0, 'rgba(255,255,255,0.42)');
    g.addColorStop(0.55, 'rgba(255,255,255,0.06)');
    g.addColorStop(1, 'rgba(0,0,0,0.20)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }

  function slot(ctx, x, y, r) {
    ctx.strokeStyle = SLOT_EDGE;
    ctx.lineWidth = Math.max(1, r * 0.14);
    ctx.setLineDash([r * 0.5, r * 0.42]);
    ctx.beginPath();
    ctx.arc(x, y, r * 0.9, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // The 2x2 answer block, BLACK FIRST: the black pegs fill from the top-left, then the whites.
  // That order is the two-pass rule made visible (js/core/codes.js), and it is why the block is
  // drawn as four fixed cells rather than as a list — a duplicate colour can never look like a
  // positional hit.
  function feedback(ctx, x, y, r, black, white) {
    const cells = [[0, 0], [1, 0], [0, 1], [1, 1]];
    const order = [];
    for (let i = 0; i < black; i++) order.push(BLACK_PEG);
    for (let i = 0; i < white; i++) order.push(WHITE_PEG);
    ctx.fillStyle = SLOT;
    roundRect(ctx, x - r * 0.25, y - r * 0.25, r * 2.5 + r * 0.5, r * 2.5 + r * 0.5, r * 0.5);
    ctx.fill();
    for (let i = 0; i < 4; i++) {
      const [cx, cy] = cells[i];
      const px = x + cx * (r * 1.5);
      const py = y + cy * (r * 1.5);
      ctx.fillStyle = SLOT_EDGE;
      ctx.beginPath();
      ctx.arc(px, py, r * 0.62, 0, Math.PI * 2);
      ctx.fill();
      if (i < order.length) {
        ctx.fillStyle = order[i];
        ctx.beginPath();
        ctx.arc(px, py, r * 0.55, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }

  // The desk the rows sit on. Flat wash first, texture second, so a missing or slow bitmap leaves
  // the board looking exactly like it did before the asset existed.
  function backdrop() {
    const w = geo.w - 8;
    const h = geo.oy + geo.rowH * MAX_ROWS;
    ctx.save();
    roundRect(ctx, 4, 4, w, h, 10);
    ctx.clip();
    ctx.fillStyle = ROW_BG;
    ctx.fillRect(4, 4, w, h);
    if (pattern) {
      // Drift is a function of `clock` (seconds), never of `frames`: the same desk slides the
      // same distance per second on a 30Hz phone and a 120Hz monitor.
      const drift = reduced ? 0 : ((clock * 7) % TEX_SIZE);
      ctx.globalAlpha = reduced ? 0.3 : 0.45;
      ctx.save();
      ctx.translate(4 - drift, 4 - drift);
      ctx.fillStyle = pattern;
      ctx.fillRect(0, 0, w + TEX_SIZE * 2, h + TEX_SIZE * 2);
      ctx.restore();
      ctx.globalAlpha = 1;
    }
    ctx.restore();
  }

  // 0..1, the amber edge breathing. Reduced motion pins it to a constant, so the row still reads
  // as "the active one" without anything pulsing.
  function pulse() {
    return reduced ? 0.5 : 0.5 + 0.5 * Math.sin(clock * 2.4);
  }

  function draw() {
    ctx.clearRect(0, 0, geo.w, geo.h);
    backdrop();
    if (!game) return;
    const r = geo.peg / 2;
    ctx.font = `${Math.round(geo.peg * 0.42)}px ui-monospace, monospace`;
    ctx.textBaseline = 'middle';

    for (let row = 0; row < MAX_ROWS; row++) {
      const done = row < game.rows.length;
      const active = row === game.rows.length && !game.done;
      const y = geo.oy + row * geo.rowH + geo.rowH / 2;
      if (active) {
        ctx.globalAlpha = 0.72 + 0.28 * pulse();
        ctx.fillStyle = ACTIVE;
        roundRect(ctx, geo.ox - 6, y - geo.rowH / 2 + 2, geo.fbX + geo.peg * 2.2 - geo.ox + 6, geo.rowH - 4, 8);
        ctx.fill();
        ctx.strokeStyle = ACTIVE_EDGE;
        ctx.lineWidth = 1;
        roundRect(ctx, geo.ox - 6, y - geo.rowH / 2 + 2, geo.fbX + geo.peg * 2.2 - geo.ox + 6, geo.rowH - 4, 8);
        ctx.stroke();
        ctx.globalAlpha = 1;
      }
      ctx.fillStyle = DIM;
      ctx.textAlign = 'right';
      ctx.fillText(String(row + 1), geo.ox - 7, y);
      ctx.textAlign = 'left';

      if (done) {
        const row0 = game.rows[row];
        const digits = space.digits;
        for (let col = 0; col < L; col++) {
          const p = pegXY(row, col);
          // The newest row grows in; older rows are already at full size.
          const t = row === game.rows.length - 1 ? 0.6 + 0.4 * anim : 1;
          peg(ctx, p.x, p.y, r * t, COLOR_SWATCH[digits[row0.guess * L + col]]);
        }
        feedback(ctx, geo.fbX, y - geo.peg * 0.62, geo.peg * 0.4, row0.black, row0.white);
        if (row0.repeat) {
          ctx.fillStyle = 'rgba(209,97,139,0.9)';
          ctx.fillText('重复', geo.fbX + geo.peg * 1.15, y);
        }
      } else if (active || row === game.rows.length) {
        for (let col = 0; col < L; col++) {
          const p = pegXY(row, col);
          if (col < game.draft.length) peg(ctx, p.x, p.y, r, COLOR_SWATCH[game.draft[col]]);
          else slot(ctx, p.x, p.y, r);
        }
      } else {
        for (let col = 0; col < L; col++) slot(ctx, pegXY(row, col).x, y, r * 0.82);
      }
    }

    // Palette: one swatch per colour, named on hover-free small screens by its first glyph.
    for (let c = 0; c < C; c++) {
      const x = geo.palX + c * geo.palR * 3;
      peg(ctx, x, geo.palY, geo.palR, COLOR_SWATCH[c]);
      ctx.fillStyle = DIM;
      ctx.textAlign = 'center';
      ctx.fillText(COLOR_NAMES[c][0], x, geo.palY + geo.palR * 1.9);
      ctx.textAlign = 'left';
    }
  }

  // The only place time moves. Everything is in seconds, so the same wall-clock duration lands
  // the same values at 30, 60 or 120Hz; `paused` returns before any accumulator is touched, which
  // is what makes pause a freeze rather than a slowdown.
  function advance(dt) {
    if (paused) return;
    if (reduced) {
      anim = 1;
      live = 0;
      return;
    }
    clock += dt;
    frames++;
    anim = Math.min(1, anim + dt * ANIM_SPEED);
    live = Math.max(0, live - dt);
  }

  function step(now) {
    raf = 0;
    const t = typeof now === 'number' ? now : 0;
    // Clamp, don't trust: a backgrounded tab hands back a multi-second dt, and the row would
    // otherwise be drawn as if it had animated for that long.
    const dt = last === null ? 0 : Math.max(0, Math.min(0.05, (t - last) / 1000));
    last = t;
    advance(dt);
    draw();
    if (paused) {
      last = null;
      return;
    }
    if (anim < 1 || live > 0) raf = window.requestAnimationFrame(step);
    else last = null;
  }

  function start() {
    if (raf || paused || reduced) return;
    last = null;
    raf = window.requestAnimationFrame(step);
  }

  return {
    setGame(g) {
      game = g;
      // Draw first: a test (or a browser that never fires another frame) must still see the
      // board it asked for. The loop only adds the growth-in on top.
      if (reduced) {
        anim = 1;
        live = 0;
      } else {
        anim = 0;
        live = LIVE_WINDOW;
      }
      draw();
      start();
    },
    measure,
    draw,
    // Pause freezes the simulation, not just the input: the accumulator stops being fed and the
    // rAF loop is parked, so nothing about the board advances while paused.
    setPaused(v) {
      paused = !!v;
      if (paused) {
        if (raf) window.cancelAnimationFrame(raf);
        raf = 0;
        last = null;
        draw();
      } else {
        start();
      }
      return paused;
    },
    get paused() { return paused; },
    setReducedMotion(v) {
      reduced = !!v;
      if (reduced) {
        if (raf) window.cancelAnimationFrame(raf);
        raf = 0;
        anim = 1;
        live = 0;
      }
      draw();
      return reduced;
    },
    // 重开 must put the clock back too, not just the rules: a stale `clock` would carry the
    // previous run's texture drift and pulse phase into the new board.
    resetClock() {
      clock = 0;
      frames = 0;
      anim = reduced ? 1 : 0;
      live = 0;
      last = null;
      draw();
    },
    stats() {
      return { clock, frames, anim, live, paused, reduced, gesture, texture: !!pattern };
    },
    // Client coordinates for a test to click. A row that is not on the board yet still has a
    // legal point — that is the row in progress.
    pegPoint(row, col) {
      const p = pegXY(row, col);
      const box = canvas.getBoundingClientRect();
      return { x: Math.round(box.left + p.x), y: Math.round(box.top + p.y), peg: geo.peg };
    },
    palettePoint(c) {
      const box = canvas.getBoundingClientRect();
      return {
        x: Math.round(box.left + geo.palX + c * geo.palR * 3),
        y: Math.round(box.top + geo.palY),
        r: geo.palR,
        hit: Math.max(geo.palR * 1.15, MIN_HIT / 2),
      };
    },
    geom() {
      return { ...geo, L, C, rows: MAX_ROWS, minHit: MIN_HIT };
    },
    destroy() {
      canvas.removeEventListener('pointerdown', down);
      canvas.removeEventListener('mousedown', down);
      if (onTouch) canvas.removeEventListener('touchstart', onTouch);
      if (raf) window.cancelAnimationFrame(raf);
      raf = 0;
    },
  };
}
